use crate::constants::{TWO_POW_119, TWO_POW_120};
use crate::fns::unconstrained_ops::{__add, __gte, __mul, __neg, __one, __pow};
use crate::params::BigNumParams as P;
use crate::utils::msb::get_msb;
use crate::utils::split_bits::__normalize_limbs;

pub(crate) unconstrained fn __from_field<let N: u32>(field: Field) -> [u128; N] {
    let mut x = field;
    let x_first_u128 = (x as u128);
    let first: u128 = x_first_u128 % TWO_POW_120;
    // this becomes the same as a integer division because we're removing the remainder
    x = (x - (first as Field)) / (TWO_POW_120 as Field);
    let x_second_u128 = (x as u128);
    let second = x_second_u128 % TWO_POW_120;
    x = (x - (second as Field)) / (TWO_POW_120 as Field);
    let x_third_u128 = (x as u128);
    let third = x_third_u128 % TWO_POW_120;
    let mut result: [u128; N] = [0; N];
    if N > 2 {
        result[0] = first;
        result[1] = second;
        result[2] = third;
    }
    if N == 2 {
        result[0] = first;
        result[1] = second;
    }
    if N == 1 {
        result[0] = first;
    }
    result
}

pub(crate) unconstrained fn __validate_in_field_compute_borrow_flags<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    val: [u128; N],
) -> [bool; N] {
    let mut flags: [bool; N] = [false; N];
    let modulus: [u128; N] = params.modulus;
    flags[0] = modulus[0] < val[0];
    for i in 1..N - 1 {
        flags[i] = modulus[i] < val[i] + flags[i - 1] as u128;
    }
    flags
}

pub(crate) unconstrained fn __validate_gt_remainder<let N: u32>(
    lhs: [u128; N],
    rhs: [u128; N],
) -> (bool, [u128; N], [bool; N], [bool; N]) {
    let mut a = lhs;
    let mut b = rhs;
    let underflow = !__gte(lhs, rhs);

    let mut result: [u128; N] = [0; N];
    // swap a and b if there's an underflow
    let (a, b) = if underflow { (b, a) } else { (a, b) };
    let mut carry_in: u128 = 0;
    let mut borrow_in: u128 = 0;
    let mut borrow_flags: [bool; N] = [false; N];
    let mut carry_flags: [bool; N] = [false; N];
    for i in 0..N {
        let mut add_term: u128 = a[i] + carry_in;
        let mut carry = (add_term as u128 >= TWO_POW_120) as u128;
        add_term -= carry * TWO_POW_120;
        carry_in = carry;

        let sub_term = b[i] + borrow_in;
        let mut borrow = (sub_term > add_term) as u128;
        result[i] = (borrow * TWO_POW_120 + add_term - sub_term);

        borrow_in = borrow;

        // Only set `borrow` and `carry` if they differ
        if (carry != borrow) {
            carry_flags[i] = carry != 0;
            borrow_flags[i] = borrow != 0;
        }
    }
    (underflow, result, carry_flags, borrow_flags)
}

pub(crate) unconstrained fn __neg_with_flags<let N: u32>(
    modulus: [u128; N],
    val: [u128; N],
) -> ([u128; N], [bool; N - 1]) {
    let mut result: [u128; N] = [0; N];
    let mut borrow_in: u128 = 0;

    let mut borrow_flags: [bool; N - 1] = [false; N - 1];
    for i in 0..N {
        let sub_term = val[i] + borrow_in;
        let borrow = (sub_term > modulus[i]) as u128;
        result[i] = borrow * TWO_POW_120 + modulus[i] - sub_term;

        borrow_in = borrow;
        if (i < N - 1) {
            borrow_flags[i] = borrow != 0;
        }
    }
    (result, borrow_flags)
}

pub(crate) unconstrained fn __add_with_flags<let N: u32>(
    modulus: [u128; N],
    lhs: [u128; N],
    rhs: [u128; N],
) -> ([u128; N], [bool; N], [bool; N - 1], bool) {
    let add_res = __helper_add(lhs, rhs);
    let overflow = __gte(add_res, modulus);

    let mut subtrahend: [u128; N] = [0; N];
    let mut result: [u128; N] = [0; N];

    if overflow {
        subtrahend = modulus;
    }

    let mut carry_in: u128 = 0;
    let mut borrow_in: u128 = 0;
    let mut borrow_flags: [bool; N - 1] = [false; N - 1];
    let mut carry_flags: [bool; N] = [false; N];
    for i in 0..N {
        let mut add_term = lhs[i] + rhs[i] + carry_in;
        let mut carry = (add_term as u128 >= TWO_POW_120) as u128;
        add_term -= carry * TWO_POW_120;
        carry_in = carry as u128;

        let sub_term = subtrahend[i] + borrow_in;

        let mut borrow: u128 = (sub_term > add_term) as u128;
        result[i] = borrow * TWO_POW_120 + add_term - sub_term;
        borrow_in = borrow as u128;

        // Only set `borrow` and `carry` if they differ
        if (carry != borrow) {
            carry_flags[i] = carry != 0;
            if (i < N - 1) {
                borrow_flags[i] = borrow != 0;
            }
        }
    }
    (result, carry_flags, borrow_flags, overflow)
}

pub(crate) unconstrained fn __sub_with_flags<let N: u32>(
    modulus: [u128; N],
    lhs: [u128; N],
    rhs: [u128; N],
) -> ([u128; N], [bool; N], [bool; N - 1], bool) {
    let mut one: [u128; N] = [0; N];
    one[0] = 1;
    let underflow = !__gte(lhs, rhs);
    let addend: [u128; N] = if underflow { modulus } else { [0; N] };
    let mut result: [u128; N] = [0; N];

    let mut carry_in: u128 = 0;
    let mut borrow_in: u128 = 0;
    let mut borrow_flags: [bool; N - 1] = [false; N - 1];
    let mut carry_flags: [bool; N] = [false; N];
    for i in 0..N {
        let mut add_term: u128 = lhs[i] + addend[i] + carry_in;
        let mut carry = (add_term as u128 >= TWO_POW_120) as u128;
        add_term -= carry * TWO_POW_120;
        carry_in = carry;

        let sub_term = rhs[i] + borrow_in;
        let mut borrow = (sub_term > add_term) as u128;
        result[i] = borrow as u128 * TWO_POW_120 + add_term - sub_term;
        borrow_in = borrow;

        // Only set `borrow` and `carry` if they differ
        if (carry != borrow) {
            carry_flags[i] = carry != 0;
            if (i < N - 1) {
                borrow_flags[i] = borrow != 0;
            }
        }
    }
    (result, carry_flags, borrow_flags, underflow)
}

/**
 * @brief BARRETT_REDUCTION_OVERFLOW_BITS defines how large an input to barrett reduction can be
 * @details maximum value = modulus^2 <<BARRETT_REDUCTION_OVERFLOW_BITS
 *          see __barrett_reduction for more details
 **/
comptime global BARRETT_REDUCTION_OVERFLOW_BITS: u32 = 4;

pub(crate) unconstrained fn __barrett_reduction<let N: u32>(
    x: [u128; 2 * N],
    redc_param: [u128; N],
    k: u32,
    modulus: [u128; N],
) -> ([u128; N], [u128; N]) {
    let mut mulout_field: [Field; 3 * N] = [0; 3 * N];
    for i in 0..(N + N) {
        for j in 0..N {
            mulout_field[i + j] += x[i] as Field * redc_param[j] as Field;
        }
    }

    let mulout: [u128; 3 * N] = __normalize_limbs(mulout_field, 3 * N);

    // When we apply the barrett reduction, the maximum value of the output will be
    // <= p * (1 + x/2^{2k})
    // where p = modulus,
    //       x = reduction input
    // if x > p * p, we need k to be larger than modulus_bits()
    // we hardcode k = 4, which means that the maximum value of x is approx. 16 * p * p
    // this should be larger than most values put into `evaluate_quadratic_expression`
    // TODO: try and detect cases where x might be too large at comptime
    // N.B. BARRETT_REDUCTION_OVERFLOW_BITS affects how `redc_param` is generated.
    // `redc_param` = 2^{modulus_bits() * 2 + BARRETT_REDUCTION_OVERFLOW_BITS} / modulus
    // NOTE: very niche edge case error that we need to be aware of:
    //       N must be large enough to cover the modulus *plus* BARRETT_REDUCTION_OVERFLOW_BITS
    //       i.e. a 359-bit prime needs (I think) 4 limbs to represent or we may overflow when calling __barrett_reduction
    let mut quotient = __shr(mulout, (k + k + BARRETT_REDUCTION_OVERFLOW_BITS));
    // the quotient has bunch of zero limbs now, so we can just take the first N limbs as a result
    let mut smaller_quotient = [0; N];
    for i in 0..N {
        smaller_quotient[i] = quotient[i] as u128;
    }

    // N.B. we assume that the shifted quotient cannot exceed 2 times original bit size.
    //      (partial_quotient_full should be just slightly larger than the modulus, we could probably represent with a size N+1 array)
    let partial_quotient_full: [Field; 3 * N] = __into_field_array(quotient);

    // quotient_mul_modulus_normalized can never exceed input value `x` so can fit into size-2 array
    let mut quotient_mul_modulus_normalized: [Field; 2 * N] = [0; 2 * N];

    // First, accumulate the products into quotient_mul_modulus_normalized
    for j in 0..N {
        for i in 0..(N + N - j) {
            quotient_mul_modulus_normalized[i + j] +=
                partial_quotient_full[i] * modulus[j] as Field;
        }
    }

    // Then, split the accumulated values and propagate higher bits
    let long_quotient_mul_modulus_normalized: [u128; 2 * N] =
        __normalize_limbs(quotient_mul_modulus_normalized, 2 * N);
    let mut quotient_mul_modulus_normalized: [u128; N] = [0; N];
    for i in 0..N {
        quotient_mul_modulus_normalized[i] = long_quotient_mul_modulus_normalized[i];
    }

    let mut long_remainder = __helper_sub(x, long_quotient_mul_modulus_normalized);
    // ugly but have to remove a bunch of zeros from this
    let mut remainder = [0; N];
    for i in 0..N {
        remainder[i] = long_remainder[i];
    }
    // barrett reduction is quirky so might need to remove a few modulus from the remainder
    if (__gte(remainder, modulus)) {
        remainder = __helper_sub(remainder, modulus);
        smaller_quotient = __increment(smaller_quotient);
    }
    if (__gte(remainder, modulus)) {
        remainder = __helper_sub(remainder, modulus);
        smaller_quotient = __increment(smaller_quotient);
    }
    if (__gte(remainder, modulus)) {
        remainder = __helper_sub(remainder, modulus);
        smaller_quotient = __increment(smaller_quotient);
    }

    (smaller_quotient, remainder)
}

/**
* @brief compute the log of the size of the primitive root
* @details find the maximum value k where x^k = 1, where x = primitive root
*          This is needed for our Tonelli-Shanks sqrt algorithm
**/
pub(crate) unconstrained fn __primitive_root_log_size<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
) -> u32 {
    let mut one: [u128; N] = [0; N];
    one[0] = 1;
    let mut target = __helper_sub(params.modulus, one);
    let mut result: u32 = 0;
    for _ in 0..MOD_BITS {
        let lsb_is_one = (target[0] & 1) == 1;
        if (lsb_is_one) {
            break;
        }
        result += 1;
        target = __shr1(target);
    }
    result
}

/**
* @brief inner loop fn for `find_multiplive_generator`
* @details recursive function to get around the lack of a `while` keyword
**/
unconstrained fn __recursively_find_multiplicative_generator<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    target: [u128; N],
    p_minus_one_over_two: [u128; N],
) -> (bool, [u128; N]) {
    let exped = __pow(params, target, p_minus_one_over_two);
    let one: [u128; N] = __one();
    let neg_one = __neg(params.modulus, one);
    let found = exped == neg_one;
    let mut result: (bool, [u128; N]) = (found, target);
    if (!found) {
        let _target: [u128; N] = __add(params.modulus, target, one);
        result = __recursively_find_multiplicative_generator::<_, MOD_BITS>(
            params,
            _target,
            p_minus_one_over_two,
        );
    }
    result
}

/**
* @brief find multiplicative generator `g` where `g` is the smallest value that is not a quadratic residue
*        i.e. smallest g where g^2 = -1
* @note WARNING if multiplicative generator does not exist, this function will enter an infinite loop!
**/
pub(crate) unconstrained fn __multiplicative_generator<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
) -> [u128; N] {
    let mut target: [u128; N] = __one();
    let p_minus_one_over_two = __shr1(__helper_sub(params.modulus, __one()));
    let (_, target) = __recursively_find_multiplicative_generator::<_, MOD_BITS>(
        params,
        target,
        p_minus_one_over_two,
    );
    target
}

pub(crate) unconstrained fn __tonelli_shanks_sqrt_inner_loop_check<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    t2m: [u128; N],
    i: u32,
) -> u32 {
    let one: [u128; N] = __one();
    let is_one = t2m == one;
    let mut result = i;
    if (!is_one) {
        let t2m = __mul::<_, MOD_BITS>(params, t2m, t2m);
        let i = i + 1;
        result = __tonelli_shanks_sqrt_inner_loop_check::<_, MOD_BITS>(params, t2m, i);
    }
    result
}

pub(crate) unconstrained fn __increment<let N: u32>(val: [u128; N]) -> [u128; N] {
    let mut result: [u128; N] = [0; N];
    let mut carry: u128 = 1;
    for i in 0..N {
        let mut add_term = (val[i] + carry);
        carry = add_term >> 120;
        add_term = add_term - (carry << 120);
        result[i] = add_term;
    }
    result
}

pub(crate) unconstrained fn __shr<let N: u32>(input: [u128; N], shift: u32) -> [u128; N] {
    let mut result: [u128; N] = [0; N];

    let num_shifted_limbs = shift / 120;
    let limb_shift = (shift % 120) as u128;
    let remainder_shift = (120 - limb_shift);
    let mask: u128 = (((1 as u128) << (limb_shift as u128)) - 1) << (remainder_shift as u128);
    result[0] = (input[0 + num_shifted_limbs] >> (limb_shift as u128));
    for i in 1..(N - num_shifted_limbs) {
        let value = input[i + num_shifted_limbs];
        result[i] = value >> (limb_shift as u128);
        let remainder: u128 = (value << (remainder_shift as u128)) & mask;
        result[i - 1] = result[i - 1] + remainder;
    }
    result
}

pub(crate) unconstrained fn __shl<let N: u32>(input: [u128; N], shift: u32) -> [u128; N] {
    let mut result: [u128; N] = [0; N];

    let num_shifted_limbs = shift / 120;
    let limb_shift = (shift % 120) as u128;
    let remainder_shift = 120 - limb_shift;

    // 83
    // limb shift = 1
    // inside shift = 19 bits to the left
    // meaning we have 19 carry bits and 41 remainder bits
    let mask: u128 = (1 as u128 << 120) - 1;
    //   let mask: u64 = (((1 as u64) << limb_shift as u8) - 1) << remainder_shift as u8;
    let value = input[0];

    let mut remainder = (value >> (remainder_shift as u128));
    result[num_shifted_limbs] = (value << (limb_shift as u128)) & mask;

    // shift 84. num shifted = 1
    for i in 1..((N) - num_shifted_limbs) {
        let value = input[i];
        let upshift = ((value << (limb_shift as u128)) + remainder) & mask;
        result[i + num_shifted_limbs] = upshift;
        remainder = (value >> (remainder_shift as u128));
    }
    result
}

pub(crate) unconstrained fn __helper_sub<let N: u32>(lhs: [u128; N], rhs: [u128; N]) -> [u128; N] {
    let mut result: [u128; N] = [0; N];
    let mut borrow: u128 = 0;
    let mut borrow_in: u128 = 0;
    for i in 0..N {
        borrow = ((rhs[i] + borrow_in) > lhs[i]) as u128;
        let sub = (borrow << 120) + lhs[i] as u128 - rhs[i] as u128 - borrow_in;
        result[i] = sub;
        borrow_in = borrow;
    }
    result
}

pub(crate) unconstrained fn __helper_add<let N: u32>(lhs: [u128; N], rhs: [u128; N]) -> [u128; N] {
    let mut result: [u128; N] = [0; N];
    let mut carry: u128 = 0;
    for i in 0..N {
        let mut add_term = (lhs[i] + rhs[i] + carry);
        carry = add_term >> 120;
        add_term = add_term - (carry << 120);
        result[i] = add_term;
    }
    result
}

pub(crate) unconstrained fn __shr1<let N: u32>(mut input: [u128; N]) -> [u128; N] {
    let value = input[N - 1];
    input[N - 1] = value >> 1;

    let mut remainder = (value & 1) << 119;

    for i in 1..N {
        let value = input[N - 1 - i];
        input[N - 1 - i] = (value >> 1) + remainder;
        remainder = (value << 119) & TWO_POW_119;
    }
    input
}

pub(crate) unconstrained fn __get_msb<let N: u32>(val: [u128; N]) -> u32 {
    let mut count = 0;
    for i in 0..N {
        let v = val[(N - 1 - i)];
        if (v > 0) {
            count = 120 * (N - 1 - i) + get_msb(v);
            break;
        }
    }
    count
}

pub(crate) fn __get_bit<let N: u32>(input: [u128; N], bit: u32) -> bool {
    let segment_index: u32 = bit / 120;
    let uint_index = (bit % 120) as u128;
    let limb: u128 = input[segment_index];
    let value = (limb >> (uint_index as u128)) & 1;
    value == 1
}

pub(crate) fn __into_field_array<let N: u32>(input: [u128; N]) -> [Field; N] {
    let mut result: [Field; N] = [0; N];
    for i in 0..N {
        result[i] = input[i] as Field;
    }
    result
}

103.source:
use crate::fns::constrained_ops::derive_from_seed;
use crate::fns::unconstrained_helpers::{
    __barrett_reduction, __get_bit, __get_msb, __helper_add, __helper_sub, __increment,
    __multiplicative_generator, __primitive_root_log_size, __shl, __shr,
    __tonelli_shanks_sqrt_inner_loop_check,
};
use crate::params::BigNumParams as P;
use crate::utils::split_bits;
use super::unconstrained_helpers::__shr1;

pub(crate) unconstrained fn __one<let N: u32>() -> [u128; N] {
    let mut limbs: [u128; N] = [0; N];
    limbs[0] = 1;
    limbs
}

/// Deterministically derives a big_num from a seed value.
///
/// Takes a seed byte array and generates a big_num in the range [0, modulus-1].
///
/// ## Value Parameters
///
/// - `params`: The BigNum parameters containing modulus and reduction info
/// - `seed`:  Input seed bytes to derive from.
///
/// ## Returns
///
///  An array of field elements derived from the seed (the limbs of the big_num)
pub(crate) unconstrained fn __derive_from_seed<let N: u32, let MOD_BITS: u32, let SeedBytes: u32>(
    params: P<N, MOD_BITS>,
    seed: [u8; SeedBytes],
) -> [u128; N] {
    let out = derive_from_seed::<N, MOD_BITS, SeedBytes>(params, seed);
    out
}

pub(crate) unconstrained fn __eq<let N: u32>(lhs: [u128; N], rhs: [u128; N]) -> bool {
    lhs == rhs
}

pub(crate) unconstrained fn __is_zero<let N: u32>(limbs: [u128; N]) -> bool {
    let mut result: bool = true;
    for i in 0..N {
        result = result & (limbs[i] == 0);
    }

    result
}

/**
* @brief given an input `x`, compute `2p - x` (unconstrained)
*
* @description we subtract the input from double the modulus, because all constrained BigNum operations
*              only guarantee that the output is in the range [0, ceil(log2(p))].
*              I.E. the input may be larger than the modulus `p`.
*              In order to ensure this operation does not underflow, we compute `2p - x` instead of `p - x`.
*              N.B. constrained BigNum operations do not fully constrain outputs to be in the range [0, p-1]
*              because such a check is expensive and usually unneccesary.
*/
pub(crate) unconstrained fn __neg<let N: u32>(modulus: [u128; N], limbs: [u128; N]) -> [u128; N] {
    __helper_sub(modulus, limbs)
}

pub(crate) unconstrained fn __add<let N: u32>(
    modulus: [u128; N],
    lhs: [u128; N],
    rhs: [u128; N],
) -> [u128; N] {
    let mut result: [u128; N] = [0; N];
    let mut carry: u128 = 0;
    for i in 0..N {
        let mut add_term = (lhs[i] + rhs[i] + carry);
        carry = add_term >> 120;
        add_term = add_term - (carry << 120);
        result[i] = add_term;
    }
    // check if the result is greater than the modulus
    if __gte(result, modulus) {
        __helper_sub(result, modulus)
    } else {
        result
    }
}

/**
* @brief given inputs `x, y` compute 2p + x - y (unconstrained)
* @description see `__neg` for why we use 2p instead of p
**/
pub(crate) unconstrained fn __sub<let N: u32>(
    modulus: [u128; N],
    lhs: [u128; N],
    rhs: [u128; N],
) -> [u128; N] {
    __add(modulus, lhs, __neg(modulus, rhs))
}

pub(crate) unconstrained fn __mul_with_quotient<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    lhs: [u128; N],
    rhs: [u128; N],
) -> ([u128; N], [u128; N]) {
    let mut mul: [Field; 2 * N] = [0; 2 * N];
    for i in 0..N {
        for j in 0..N {
            mul[i + j] += (lhs[i] as Field * rhs[j] as Field);
        }
    }
    let to_reduce: [u128; (N * 2)] = split_bits::__normalize_limbs(mul, 2 * N);
    let (q, r) = __barrett_reduction(to_reduce, params.redc_param, MOD_BITS, params.modulus);
    (q, r)
}

pub(crate) unconstrained fn __mul<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    lhs: [u128; N],
    rhs: [u128; N],
) -> [u128; N] {
    let (_, b) = __mul_with_quotient::<_, MOD_BITS>(params, lhs, rhs);
    b
}

pub(crate) unconstrained fn __div<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    numerator: [u128; N],
    divisor: [u128; N],
) -> [u128; N] {
    let inv_divisor: [u128; N] = __invmod::<_, MOD_BITS>(params, divisor);
    __mul::<_, MOD_BITS>(params, numerator, inv_divisor)
}

/**
* @brief __udiv_mod performs *unconstrained* integer division between numerator, divisor 
*
* i.e. 1. floor(numerator / divisor) = quotient
*      2. numerator % divisor = remainder
*      3. divisor * quotient + remainder = numerator
**/
pub(crate) unconstrained fn __udiv_mod<let N: u32>(
    numerator: [u128; N],
    divisor: [u128; N],
) -> ([u128; N], [u128; N]) {
    let mut quotient: [u128; N] = [0; N];
    let mut remainder: [u128; N] = numerator;

    let b = divisor;
    let numerator_msb = __get_msb(numerator);
    let divisor_msb = __get_msb(divisor);
    if divisor_msb > numerator_msb {
        ([0; N], numerator)
    } else {
        let mut bit_difference = __get_msb(remainder) - __get_msb(divisor);
        let mut accumulator: [u128; N] = __one();
        let mut divisor = __shl(divisor, bit_difference);
        accumulator = __shl(accumulator, bit_difference);

        if (__gte(divisor, __increment(remainder))) {
            divisor = __shr1(divisor);
            accumulator = __shr1(accumulator);
        }

        for _ in 0..(N * 120) {
            if (__gte(remainder, b) == false) {
                break;
            }
            // we've shunted 'divisor' up to have the same bit length as our remainder.
            // If remainder >= divisor, then a is at least '1 << bit_difference' multiples of b
            if (__gte(remainder, divisor)) {
                remainder = __helper_sub(remainder, divisor);
                // we can use OR here instead of +, as
                // accumulator is always a nice power of two
                quotient = __helper_add(quotient, accumulator);
            }
            divisor = __shr1(divisor); // >>= 1;
            accumulator = __shr1(accumulator); //  >>= 1;
        }

        (quotient, remainder)
    }
}

pub(crate) unconstrained fn __invmod<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    val: [u128; N],
) -> [u128; N] {
    let one = __one();
    let exp = __helper_sub(params.modulus, __helper_add(one, one));
    __pow::<_, MOD_BITS>(params, val, exp)
}

pub(crate) unconstrained fn __pow<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    val: [u128; N],
    exponent: [u128; N],
) -> [u128; N] {
    let x = exponent;
    let num_bits = MOD_BITS + 1;

    let mut accumulator: [u128; N] = __one::<N>();

    for i in 0..num_bits {
        accumulator = __mul::<_, MOD_BITS>(params, accumulator, accumulator);
        if __get_bit(x, num_bits - i - 1) {
            accumulator = __mul::<_, MOD_BITS>(params, accumulator, val);
        }
    }
    accumulator
}

pub(crate) unconstrained fn batch_invert<let N: u32, let MOD_BITS: u32, let M: u32>(
    params: P<N, MOD_BITS>,
    x: [[u128; N]; M],
) -> [[u128; N]; M] {
    // TODO: ugly! Will fail if input slice is empty

    let mut accumulator: [u128; N] = __one::<N>();
    let mut temporaries: [[u128; N]; M] = std::mem::zeroed();

    for i in 0..M {
        temporaries[i] = accumulator;
        if (!__is_zero(x[i])) {
            accumulator = __mul::<_, MOD_BITS>(params, accumulator, x[i]);
        }
    }

    let mut result: [[u128; N]; M] = [[0; N]; M];
    accumulator = __invmod::<_, MOD_BITS>(params, accumulator);
    for i in 0..M {
        let idx = M - 1 - i;
        if (!__is_zero(x[idx])) {
            let T0 = __mul::<_, MOD_BITS>(params, accumulator, temporaries[idx]);
            accumulator = __mul::<_, MOD_BITS>(params, accumulator, x[idx]);
            result[idx] = T0;
        }
    }
    result
}

pub(crate) unconstrained fn batch_invert_slice<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    x: [[u128; N]],
) -> [[u128; N]] {
    // TODO: ugly! Will fail if input slice is empty
    let mut accumulator: [u128; N] = __one::<N>();
    let mut temporaries: [[u128; N]] = &[];
    for i in 0..x.len() {
        temporaries = temporaries.push_back(accumulator);
        if (!__is_zero(x[i])) {
            accumulator = __mul::<_, MOD_BITS>(params, accumulator, x[i]);
        }
    }

    let mut result: [[u128; N]] = [];
    accumulator = __invmod::<_, MOD_BITS>(params, accumulator);
    for i in 0..x.len() {
        let idx = x.len() - 1 - i;
        if (!__is_zero(x[idx])) {
            let T0 = __mul::<_, MOD_BITS>(params, accumulator, temporaries[idx]);
            accumulator = __mul::<_, MOD_BITS>(params, accumulator, x[idx]);
            result = result.push_front(T0);
        } else {
            result = result.push_front([0; N]);
        };
    }

    result
}

/**
* @brief compute a modular square root using the Tonelli-Shanks algorithm
* @details only use for prime fields! Function may infinite loop if used for non-prime fields
* @note this is unconstrained fn. To constrain a square root, validate that output^2 = self
* TODO: create fn that constrains nonexistence of square root (i.e. find x where x^2 = -self)
**/
pub(crate) unconstrained fn __tonelli_shanks_sqrt<let N: u32, let MOD_BITS: u32>(
    params: P<N, MOD_BITS>,
    input: [u128; N],
) -> std::option::Option<[u128; N]> {
    // Tonelli-shanks algorithm begins by finding a field element Q and integer S,
    // such that (p - 1) = Q.2^{s}
    // We can compute the square root of a, by considering a^{(Q + 1) / 2} = R
    // Once we have found such an R, we have
    // R^{2} = a^{Q + 1} = a^{Q}a
    // If a^{Q} = 1, we have found our square root.
    // Otherwise, we have a^{Q} = t, where t is a 2^{s-1}'th root of unity.
    // This is because t^{2^{s-1}} = a^{Q.2^{s-1}}.
    // We know that (p - 1) = Q.w^{s}, therefore t^{2^{s-1}} = a^{(p - 1) / 2}
    // From Euler's criterion, if a is a quadratic residue, a^{(p - 1) / 2} = 1
    // i.e. t^{2^{s-1}} = 1
    // To proceed with computing our square root, we want to transform t into a smaller subgroup,
    // specifically, the (s-2)'th roots of unity.
    // We do this by finding some value b,such that
    // (t.b^2)^{2^{s-2}} = 1 and R' = R.b
    // Finding such a b is trivial, because from Euler's criterion, we know that,
    // for any quadratic non-residue z, z^{(p - 1) / 2} = -1
    // i.e. z^{Q.2^{s-1}} = -1
    // => z^Q is a 2^{s-1}'th root of -1
    // => z^{Q^2} is a 2^{s-2}'th root of -1
    // Since t^{2^{s-1}} = 1, we know that t^{2^{s - 2}} = -1
    // => t.z^{Q^2} is a 2^{s - 2}'th root of unity.
    // We can iteratively transform t into ever smaller subgroups, until t = 1.
    // At each iteration, we need to find a new value for b, which we can obtain
    // by repeatedly squaring z^{Q}
    let one = __one();
    let primitive_root_log_size = __primitive_root_log_size::<_, MOD_BITS>(params);
    let Q = __shr(
        __helper_sub(params.modulus, one),
        primitive_root_log_size - 1,
    );
    let two = __helper_add(one, one);
    let Q_minus_one_over_two = __shr(__helper_sub(Q, two), 2);
    let mut z = __multiplicative_generator::<_, MOD_BITS>(params); // the generator is a non-residue
    let mut b = __pow::<_, MOD_BITS>(params, input, Q_minus_one_over_two);
    let mut r = __mul::<_, MOD_BITS>(params, input, b);
    let mut t = __mul::<_, MOD_BITS>(params, r, b);
    let mut check: [u128; N] = t;
    for _ in 0..primitive_root_log_size - 1 {
        check = __mul::<_, MOD_BITS>(params, check, check);
    }
    let mut result = Option::none();
    if (__eq(check, one)) {
        let mut t1 = __pow::<_, MOD_BITS>(params, z, Q_minus_one_over_two);
        let mut t2 = __mul::<_, MOD_BITS>(params, t1, z);
        let mut c = __mul::<_, MOD_BITS>(params, t2, t1);
        let mut m: u32 = primitive_root_log_size;
        // tonelli shanks inner 1
        // (if t2m == 1) then skip
        // else increase i and square t2m and go again
        // algorithm runtime should only be max the number of bits in modulus
        for _ in 0..MOD_BITS {
            if (__eq(t, one)) {
                result = Option::some(r);
                break;
            }
            let mut t2m = t;
            // while loop time
            let i = __tonelli_shanks_sqrt_inner_loop_check::<_, MOD_BITS>(params, t2m, 0);
            let mut j = m - i - 1;
            b = c;
            for _ in 0..j {
                // how big
                if (j == 0) {
                    break;
                }
                b = __mul(params, b, b);
                //j -= 1;
            }
            c = __mul::<_, MOD_BITS>(params, b, b);
            t = __mul::<_, MOD_BITS>(params, t, c);
            r = __mul::<_, MOD_BITS>(params, r, b);
            m = i;
        }
    }
    result
}

pub(crate) unconstrained fn __gte<let N: u32>(lhs: [u128; N], rhs: [u128; N]) -> bool {
    let mut result = false;
    let mut early_exit = false;
    for i in 0..(N) {
        let idx = (N) - 1 - i;
        if (rhs[idx] == lhs[idx]) {
            continue;
        }

        result = rhs[idx] < lhs[idx];
        early_exit = true;
        break;
    }
    if early_exit {
        result
    } else {
        lhs[0] == rhs[0]
    }
}

